from pathlib import Path
import base64
import runpy

BASE_INSTALLER = ''
FILES = {'apps/context41/forms.py': '', 'apps/context41/services.py': '', 'apps/context41/views.py': ''}
TEMPLATE_PATCH = ''
JS_PATCH = ''
CSS_APPEND = ''

tmp = Path("_ctx41_v69_base.py")
tmp.write_bytes(
    base64.b64decode(BASE_INSTALLER)
)

print("=== INSTALANDO CONTEXT 4.1 BASE ===")
runpy.run_path(
    str(tmp),
    run_name="__main__",
)

try:
    tmp.unlink()
except OSError:
    pass

print("")
print("=== ACTIVANDO ACTUALIZACIÓN AUTOMÁTICA DE VERSIONES ===")

for filename, encoded in FILES.items():
    path = Path(filename)

    backup = path.with_name(
        path.name + ".before_v69_1.bak"
    )

    if path.exists() and not backup.exists():
        backup.write_text(
            path.read_text(
                encoding="utf-8"
            ),
            encoding="utf-8",
        )

    path.write_bytes(
        base64.b64decode(encoded)
    )

    print("OK:", filename)

patch = Path("_ctx41_template_patch.py")
patch.write_bytes(
    base64.b64decode(
        TEMPLATE_PATCH
    )
)
runpy.run_path(
    str(patch),
    run_name="__main__",
)
patch.unlink()

patch = Path("_ctx41_js_patch.py")
patch.write_bytes(
    base64.b64decode(
        JS_PATCH
    )
)
runpy.run_path(
    str(patch),
    run_name="__main__",
)
patch.unlink()

css_path = Path(
    "static/css/context41_v69.css"
)
css = css_path.read_text(
    encoding="utf-8"
)
css_block = base64.b64decode(
    CSS_APPEND
).decode("utf-8")

if ".context41-auto-note" not in css:
    css_path.write_text(
        css.rstrip()
        + "\n\n"
        + css_block
        + "\n",
        encoding="utf-8",
    )
    print(
        "OK: static/css/context41_v69.css"
    )

print("")
print("V69.1 FULL instalada.")
print("")
print("Comportamiento de actualización:")
print("1. Misión/FODA PDF -> la nueva versión aparece inmediatamente en el visor.")
print("2. Lista legal Excel -> se reimporta automáticamente y la tabla cambia al guardar.")
print("3. Organigrama PDF -> el PDF vigente cambia inmediatamente.")
print("4. El organigrama interactivo NO se sobrescribe desde el PDF; conserva la jerarquía editable.")
print("5. Ninguna versión anterior se elimina.")
print("")
print("Siguiente comando: python patch_context41_v69.py")
